"use client";

import { CandlestickSeries, ColorType, CrosshairMode, createChart, HistogramSeries, LineSeries, createSeriesMarkers, type IChartApi, type Time, type UTCTimestamp } from "lightweight-charts";
import { useEffect, useMemo, useRef, useState } from "react";
import { RefreshCw, Settings2, Maximize2 } from "lucide-react";
import { useTrades } from "@/hooks/use-trades";
import { calculateTradeMetrics, formatCurrency, type Trade, type TradeMetric } from "@/lib/trades";
import { BottomNav } from "@/components/layout/bottom-nav";

type Candle = { time: Time; open: number; high: number; low: number; close: number; volume: number };
type Detail = { kind: "entry" | "exit"; label: string; price: number; qty: number; metric: TradeMetric };
const ranges = ["1M", "3M", "6M", "1Y", "2Y"] as const;
const intervals = [{ label: "1D", value: "1d" }, { label: "1H", value: "1h" }, { label: "15m", value: "15m" }, { label: "5m", value: "5m" }, { label: "1m", value: "1m" }];
function avg(data: Candle[], n: number, ema = false) { let last = data[0]?.close ?? 0; return data.flatMap((x, i) => { if (ema) last = x.close * (2 / (n + 1)) + last * (1 - 2 / (n + 1)); else if (i >= n - 1) last = data.slice(i - n + 1, i + 1).reduce((s, y) => s + y.close, 0) / n; return i >= n - 1 ? [{ time: x.time, value: last }] : []; }); }
function chartTime(value: string, daily: boolean): Time { if (daily) { if (/^\d{4}-\d{2}-\d{2}$/.test(value)) return value; return new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Kolkata", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date(value)); } return Math.floor(new Date(value).getTime() / 1000) as UTCTimestamp; }
function tradeDetails(trades: Trade[], metrics: TradeMetric[], symbol: string, date: string) { const out: Detail[] = []; trades.filter(t => t.name === symbol).forEach(t => { const metric = metrics.find(m => m.id === t.id); if (!metric) return; const entries = [["Entry", t.entry, t.initialQty, t.date], ["Scale-in", t.p1Price, t.p1Qty, t.p1Date], ["Scale-in", t.p2Price, t.p2Qty, t.p2Date]] as const; const exits = [["E1", t.e1Price, t.e1Qty, t.e1Date], ["E2", t.e2Price, t.e2Qty, t.e2Date], ["E3", t.e3Price, t.e3Qty, t.e3Date]] as const; entries.forEach(([label, price, qty, d]) => { if (d && chartTime(d, true) === date && Number(price) > 0 && Number(qty) > 0) out.push({ kind: "entry", label, price: Number(price), qty: Number(qty), metric }); }); exits.forEach(([label, price, qty, d]) => { if (d && chartTime(d, true) === date && Number(price) > 0 && Number(qty) > 0) { const exit = metric.exits.find((item) => item.label === label && item.price === Number(price) && item.qty === Number(qty)); out.push({ kind: "exit", label, price: Number(price), qty: Number(qty), metric: exit ? { ...metric, realized: exit.realizedPL, portfolioImpact: exit.portfolioImpact, cummPF: exit.cummPF, rewardRisk: exit.rMultiple } : metric }); } }); }); return out; }
function markersFor(trades: Trade[], symbol: string, daily: boolean) { return trades.filter(t => t.name === symbol).flatMap(t => [[t.date, Number(t.entry), "Entry", "belowBar", "#15955f", "arrowUp"], [t.p1Date || t.date, Number(t.p1Price), "Scale-in", "belowBar", "#2864dd", "arrowUp"], [t.p2Date || t.date, Number(t.p2Price), "Scale-in", "belowBar", "#2864dd", "arrowUp"], [t.e1Date, Number(t.e1Price), "E1", "aboveBar", "#e14f69", "arrowDown"], [t.e2Date, Number(t.e2Price), "E2", "aboveBar", "#e14f69", "arrowDown"], [t.e3Date, Number(t.e3Price), "E3", "aboveBar", "#e14f69", "arrowDown"]] as const).filter(x => x[0] && x[1] > 0).map(x => ({ time: chartTime(x[0]!, daily) as UTCTimestamp, position: x[3] as "aboveBar" | "belowBar", color: x[4], shape: x[5] as "arrowUp" | "arrowDown", text: x[2] })); }

export function StockChart() {
  const { trades } = useTrades(); const ref = useRef<HTMLDivElement>(null); const chart = useRef<IChartApi | null>(null); const [symbol, setSymbol] = useState(""); const [range, setRange] = useState("1Y"); const [interval, setInterval] = useState("1d"); const [ma1, setMa1] = useState<"EMA" | "SMA">("EMA"); const [ma2, setMa2] = useState<"EMA" | "SMA">("EMA"); const [candles, setCandles] = useState<Candle[]>([]); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); const [losers, setLosers] = useState(false); const [hover, setHover] = useState<{ date: string; x: number; y: number; volume: number } | null>(null);
  const symbols = useMemo(() => [...new Set(trades.map(t => t.name).filter(Boolean))], [trades]); const selected = symbol || symbols[0] || "NETWEB"; const metrics = useMemo(() => calculateTradeMetrics(trades, new Date(), 0), [trades]);
  const load = async () => { setLoading(true); setError(""); try { const r = await fetch(`/api/prices/candles?symbol=${encodeURIComponent(selected)}&range=${range}&interval=${interval}`, { cache: "no-store" }); const json = await r.json(); if (!r.ok) throw new Error(json.error); setCandles((json.ticks ?? []).map((x: string[]) => ({ time: chartTime(x[0], interval === "1d"), open: +x[1], high: +x[2], low: +x[3], close: +x[4], volume: +x[5] })).filter((x: Candle) => (typeof x.time === "string" ? /^\d{4}-\d{2}-\d{2}$/.test(x.time) : Number.isFinite(x.time)) && x.high > 0)); } catch (e) { setError(e instanceof Error ? e.message : "Unable to load candles"); setCandles([]); } finally { setLoading(false); } };
  // Fetch market data when chart controls change.
  // eslint-disable-next-line react-hooks/set-state-in-effect, react-hooks/exhaustive-deps
  useEffect(() => { void load(); }, [selected, range, interval]);
  useEffect(() => { if (!ref.current || !candles.length) return; const api = createChart(ref.current, { autoSize: true, layout: { background: { type: ColorType.Solid, color: "#fff" }, textColor: "#69736c" }, grid: { vertLines: { color: "#f1f4f2" }, horzLines: { color: "#f1f4f2" } }, crosshair: { mode: CrosshairMode.Normal }, rightPriceScale: { borderColor: "#e5eae6" } }); const cs = api.addSeries(CandlestickSeries, { upColor: "#16a05d", downColor: "#ef4f5f", borderUpColor: "#16a05d", borderDownColor: "#ef4f5f", wickUpColor: "#16a05d", wickDownColor: "#ef4f5f" }); cs.setData(candles); const vol = api.addSeries(HistogramSeries, { priceFormat: { type: "volume" }, priceScaleId: "" }); vol.priceScale().applyOptions({ scaleMargins: { top: .82, bottom: 0 } }); vol.setData(candles.map(x => ({ time: x.time, value: x.volume, color: x.close >= x.open ? "#9bdab7" : "#f4a0a8" }))); const m1 = api.addSeries(LineSeries, { color: "#2864dd", lineWidth: 2, title: `${ma1} 10` }); m1.setData(avg(candles, 10, ma1 === "EMA")); const m2 = api.addSeries(LineSeries, { color: "#ef5b62", lineWidth: 2, title: `${ma2} 20` }); m2.setData(avg(candles, 20, ma2 === "EMA")); createSeriesMarkers(cs, markersFor(trades, selected, interval === "1d")); api.subscribeCrosshairMove(param => { if (!param.time || !param.point) return setHover(null); const c = candles.find(x => String(x.time) === String(param.time)); if (c) setHover({ date: String(c.time).slice(0, 10), x: param.point.x, y: param.point.y, volume: c.volume }); }); api.timeScale().fitContent(); chart.current = api; return () => api.remove(); }, [candles, selected, trades, ma1, ma2, interval]);
  const shown = metrics.filter(t => losers ? t.grossPL < 0 : t.grossPL > 0).sort((a, b) => Math.abs(b.grossPL) - Math.abs(a.grossPL)).slice(0, 5); const details = hover ? tradeDetails(trades, metrics, selected, hover.date) : [];
  return <main className="min-h-screen bg-white pb-24 text-[#202923]"><section className="mx-auto max-w-[1500px] px-4 pt-6"><div className="flex flex-wrap gap-3">{[["Total trades", trades.length], ["Win rate", `${metrics.length ? Math.round(metrics.filter(t => t.grossPL > 0).length / metrics.length * 100) : 0}%`], ["Total P&L", formatCurrency(metrics.reduce((s, t) => s + t.grossPL, 0))], ["Active stocks", symbols.length]].map(([label, value]) => <div key={String(label)} className="min-w-[150px] flex-1 rounded-2xl border border-[#edf0ee] p-4"><p className="text-xs font-bold uppercase tracking-wide text-[#69736c]">{label}</p><p className="mt-2 text-2xl font-bold">{value}</p></div>)}</div><div className="mt-8 flex items-center justify-between gap-3"><h1 className="text-2xl font-bold italic">{losers ? "Top Losers" : "Top Winners"}</h1><div className="flex gap-1 rounded-xl bg-[#f6f8f6] p-1"><button onClick={() => setLosers(false)} className="rounded-lg px-3 py-2 text-sm font-semibold">Winners</button><button onClick={() => setLosers(true)} className="rounded-lg px-3 py-2 text-sm font-semibold">Losers</button></div></div><div className="mt-4 grid gap-3 md:grid-cols-2 lg:grid-cols-3">{shown.map(t => <article key={t.id} className="flex items-center gap-3 rounded-2xl border border-[#edf0ee] p-4"><span className="flex size-9 items-center justify-center rounded-full bg-[#f6f8f6] text-xs font-bold">{t.tradeNo}</span><div className="min-w-0 flex-1"><p className="truncate font-bold">{t.name}</p><p className="text-xs text-[#69736c]">{t.setup || "No Setup"} · {t.date}</p></div><p className={`font-bold ${t.grossPL >= 0 ? "text-[#00945a]" : "text-[#e14f69]"}`}>{t.grossPL >= 0 ? "+" : ""}{formatCurrency(t.grossPL)}</p></article>)}</div><header className="mt-8 flex flex-wrap items-center gap-3 border-y border-[#edf0ee] py-4"><label>MA 10 <select value={ma1} onChange={e => setMa1(e.target.value as "EMA" | "SMA")}><option>EMA</option><option>SMA</option></select></label><label>MA 20 <select value={ma2} onChange={e => setMa2(e.target.value as "EMA" | "SMA")}><option>EMA</option><option>SMA</option></select></label><select value={selected} onChange={e => setSymbol(e.target.value)}>{symbols.map(s => <option key={s}>{s}</option>)}</select><select value={range} onChange={e => setRange(e.target.value)}>{ranges.map(r => <option key={r}>{r}</option>)}</select><select value={interval} onChange={e => setInterval(e.target.value)}>{intervals.map(i => <option key={i.value} value={i.value}>{i.label}</option>)}</select><button onClick={load} aria-label="Refresh"><RefreshCw size={18} /></button><Settings2 size={20} /><Maximize2 size={20} /></header><div className="relative mt-4 rounded-2xl bg-[#fcfdfc] p-2"><div ref={ref} className="h-[560px] w-full" />{hover && <div className="pointer-events-none absolute z-10 w-72 rounded-2xl border bg-white p-4 shadow-xl" style={{ left: Math.min(Math.max(12, hover.x + 16), 650), top: Math.min(Math.max(12, hover.y - 80), 430) }}><p className="text-lg font-bold">{new Date(`${hover.date}T00:00:00`).toLocaleDateString("en-IN", { weekday: "long", day: "numeric", month: "long", year: "numeric" })}</p><hr className="my-3" /><p className="text-sm text-[#69736c]">Volume: <b className="float-right text-[#202923]">{hover.volume.toFixed(2)}</b></p>{details.map((d, i) => <div key={`${d.label}-${i}`} className={`mt-3 rounded-lg p-3 ${d.kind === "exit" ? "bg-[#fff1f2] text-[#d71920]" : "bg-[#effaf3] text-[#15955f]"}`}><p className="font-bold">{d.kind === "exit" ? "↘ Exit Point" : "↗ Entry Point"}</p><p className="mt-2 text-sm font-semibold">{d.label}: {formatCurrency(d.price)}<br />Quantity: {d.qty}<br />Realized P/L: {formatCurrency(d.metric.realized)}
Overall R/R: {d.metric.rewardRisk.toFixed(2)}R
PF Impact: {d.metric.portfolioImpact.toFixed(2)}%<br />PF Impact: {d.metric.portfolioImpact.toFixed(2)}%</p></div>)}</div>}{loading && <p className="absolute inset-0 grid place-items-center bg-white/70">Loading candles…</p>}{error && <p className="p-4 text-center text-[#d71920]">{error}</p>}</div></section><BottomNav /></main>;
}
